head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[accordion > P > selectedPanel]<br/>Accordion 컴포넌트의 초기 렌더링 시 열릴 패널을 설정합니다.",
    "validation" : [
        "selectedPanel 으로 지정한 ID 의 패널이 초기 렌더링 시 열린 상태로 표시됩니다.",
        "selectedPanel 은 열릴 패널의 ID 를 한 개만 설정합니다.",
        "selectedPanel 으로 지정한 패널의 disabledPanels=true 이면 해당 패널이 열리지 않습니다.",
        "selectedPanel 값을 설정하지 않으면 첫 번째 비활성화(disabled) 되지 않은 패널만 열린 상태로 렌더링됩니다.",
        "selectedPanel 으로 설정한 ID 값에 해당하는 패널이 없으면 모든 패널이 닫힌 상태로 렌더링됩니다.",
        "collapseAll=true 이면 selectedPanel 속성은 무시되어 지정한 패널이 열리지 않습니다.",
        "unCollapseAll=true 이면 selectedPanel 속성은 무시되어 모든 패널이 열린 상태로 렌더링됩니다.",
        "unCollapseAll=false 이고 collapseAll=false 인 경우에만 selectedPanel 속성이 동작합니다.",
        "selectedPanel 속성을 생략하면 기본값(빈 문자열) 으로 동작합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        selectedPanel : con_selectedPanel.getValue(),
        collapseAll : con_collapseAll.getText(),
        unCollapseAll : con_unCollapseAll.getText(),
    };

    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    $c.gcm.createLabel('label="* selectedPanel=panels2 : 초기 렌더링 시 panels2 만 열린 상태로 표시"', '', 'label1');
    $c.gcm.createLabel('label="* selectedPanel=panels2 + con_panel1Disabled=true : 패널 활성화 영향 없이 panels2 만 열림 / selectedPanel=panels2 + con_panel2Disabled=true : disabled 라 panels2 열리지 않음"', '', 'label2');
    $c.gcm.createLabel('label="* selectedPanel=빈값 : 첫 번째 비-disabled 패널만 열림 (panels1 이 disabled 면 panels2 가 첫 비-disabled 로 열림)"', '', 'label3');
    $c.gcm.createLabel('label="* selectedPanel=nonExist : 존재하지 않는 ID 이므로 모든 패널 닫힌 상태"', '', 'label4');
    $c.gcm.createLabel('label="* collapseAll=true 또는 unCollapseAll=true 이면 selectedPanel 무시 (collapseAll 우선 → 모두 닫힘 / unCollapseAll 우선 → 모두 열림)"', '', 'label5');

    // panel1 / panel2 의 disabledPanels 값 (con_panel1Disabled, con_panel2Disabled 콤보 기반)
    let panel1Disabled = con_panel1Disabled.getText();
    let panel2Disabled = con_panel2Disabled.getText();

    strTarget += '<w2:accordion ' + strNameSpace + ' ' + cList + ' id="" style="width:240px; height:320px;">';
    strTarget += '<w2:panels style="" id="panels1" class="" disabledPanels="' + panel1Disabled + '">';
    strTarget += '<w2:panelTitle style="" id="panelTitle1" label="panelTitle1"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent1">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel1"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels2" class="" disabledPanels="' + panel2Disabled + '">';
    strTarget += '<w2:panelTitle style="" id="panelTitle2" label="panelTitle2"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent2">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel2"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels3" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle3" label="panelTitle3"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent3">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel3"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '</w2:accordion>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "accordion",
        strTarget,
        grp_comp
    );
}



// 현재 열린 패널 정보 출력
scwin.btn_getOpenPanel_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("===== getOpenPanelInfo() 결과 =====");
    let info = target1.getOpenPanelInfo();
    if (info && info.id) {
        wf_body_bottom.getObj("scwin").setReturnValue("첫 번째 열린 패널 id : " + info.id);
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("열린 패널 없음 (모두 닫힘)");
    }

    wf_body_bottom.getObj("scwin").setReturnValue("===== getOpenPanelListInfo() 결과 =====");
    let openList = target1.getOpenPanelListInfo();
    wf_body_bottom.getObj("scwin").setReturnValue("열린 패널 수 : " + (openList ? openList.length : 0));
    if (openList && openList.length > 0) {
        for (let i = 0; i < openList.length; i++) {
            wf_body_bottom.getObj("scwin").setReturnValue("열린 패널[" + i + "] id : " + openList[i].id);
        }
    }
};
